package com.questionservice.presentation.response;
import com.questionservice.domain.model.*; import java.time.Instant; import java.util.*;
public record QuestionResponse(UUID id,String facultyId,UUID subjectId,UUID chapterId,UUID topicId,String content,String imageUrl,String storageKey,QuestionType type,Difficulty difficulty,QuestionStatus status,QuestionSource source,UUID createdBy,Instant createdAt,Instant updatedAt,List<OptionResponse> options,List<ReviewResponse> reviewHistory){public record OptionResponse(UUID id,String label,String content,String imageUrl,String storageKey,boolean correct,int sortOrder){}public record ReviewResponse(UUID id,UUID reviewerId,ReviewAction action,String comment,Instant timestamp){}
 public static QuestionResponse from(Question q){return new QuestionResponse(q.id(),q.facultyId(),q.subjectId(),q.chapterId(),q.topicId(),q.content(),q.imageUrl(),q.storageKey(),q.type(),q.difficulty(),q.status(),q.source(),q.createdBy(),q.createdAt(),q.updatedAt(),q.options().stream().map(o->new OptionResponse(o.id(),o.label(),o.content(),o.imageUrl(),o.storageKey(),o.correct(),o.sortOrder())).toList(),q.reviewHistory().stream().map(h->new ReviewResponse(h.id(),h.reviewerId(),h.action(),h.comment(),h.createdAt())).toList());}}
